164	    /**
165	     * Return this owner's identity key: the single value all duplicate detection is based on,
166	     * formed as {@code normalizedTelephone + '|' + email + '|' + householdId} (an absent email or
167	     * household id contributes an empty segment). Two owners are duplicates only when their whole
168	     * identity keys are equal, so members of the same household with different telephones — and thus
169	     * different keys — are distinct. The telephone and email are expected to already be in their
170	     * normalized storage form.
171	     */
172	    @Transient
173	    public String getIdentityKey() {
174	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
