247	    /**
248	     * Return the Pet with the given name, or null if none found for this Owner.
249	     *
250	     * @param name to test
251	     * @return true if pet name is already in use
252	     */
253	    public Pet getPet(String name) {
254	        return getPet(name, false);
255	    }
256	
257	    /**
258	     * Return the Pet with the given name, or null if none found for this Owner.
259	     *
260	     * @param name to test
261	     * @return true if pet name is already in use
262	     */
263	    public Pet getPet(String name, boolean ignoreNew) {
264	        name = name.toLowerCase();
265	        for (Pet pet : getPetsInternal()) {
266	            if (!ignoreNew || !pet.isNew()) {
267	                String compName = pet.getName();
268	                compName = compName.toLowerCase();
269	                if (compName.equals(name)) {
270	                    return pet;
271	                }
272	            }
273	        }
274	        return null;
275	    }
276	
277	    public Pet getPet(Integer petId) {
278	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
279	    }
