281	    @Override
282	    public String toString() {
283	        return new ToStringCreator(this)
284	
285	            .append("id", this.getId())
286	            .append("new", this.isNew())
287	            .append("lastName", this.getLastName())
288	            .append("firstName", this.getFirstName())
