53	 * @author Alexander Dudkin
54	 */
55	@ControllerAdvice
56	public class ExceptionControllerAdvice {
57	
58	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
59	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
60	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
61	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
62	
63	    /**
64	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
65	     * class.
66	     *
67	     * @param e     Object referring to the thrown exception.
68	     * @param status HTTP response status.
69	     * @param url URL request.
70	     */
71	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
72	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
73	        problemDetail.setType(URI.create(url.toString()));
74	        problemDetail.setTitle(e.getClass().getSimpleName());
75	        problemDetail.setDetail(detail);
76	        problemDetail.setProperty("timestamp", Instant.now());
77	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
78	        return problemDetail;
79	    }
80	
81	    /**
82	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
83	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
84	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
85	     * would catch it and report an authorization failure as a 500.
86	     *
87	     * @param e The {@link AccessDeniedException} to propagate
88	     * @throws AccessDeniedException always
89	     */
90	    @ExceptionHandler(AccessDeniedException.class)
91	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
92	        throw e;
93	    }
94	
95	    /**
96	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
97	     *
98	     * @param e The {@link Exception} to be handled
99	     * @param request {@link HttpServletRequest} object referring to the current request.
100	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
101	     */
102	    @ExceptionHandler(Exception.class)
103	    @ResponseBody
104	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
105	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
106	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
107	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
108	        return ResponseEntity.status(status).body(detail);
109	    }
110	
111	    /**
112	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
113	     * method returns a 404 Not Found status if an entity does not exist.
114	     *
115	     * @param e The {@link DataIntegrityViolationException} to be handled
116	     * @param request {@link HttpServletRequest} object referring to the current request.
117	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
118	     */
119	    @ExceptionHandler(DataIntegrityViolationException.class)
120	    @ResponseBody
121	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
122	        logger.warn("Data integrity violation at {} {}: {}",
123	            request.getMethod(),
124	            request.getRequestURI(),
125	            e.getMessage());
126	        logger.debug("Data integrity violation stacktrace", e);
127	        HttpStatus status = HttpStatus.NOT_FOUND;
128	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
129	        return ResponseEntity.status(status).body(detail);
130	    }
131	
132	    /**
133	     * Handles exception thrown by Bean Validation on controller methods parameters
134	     *
135	     * @param e The {@link MethodArgumentNotValidException} to be handled
136	     * @param request {@link HttpServletRequest} object referring to the current request.
137	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
138	     */
139	    @ExceptionHandler(MethodArgumentNotValidException.class)
140	    @ResponseBody
141	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
142	        HttpStatus status = HttpStatus.BAD_REQUEST;
143	        BindingErrorsResponse errors = new BindingErrorsResponse();
144	        BindingResult bindingResult = e.getBindingResult();
145	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
146	        List<String> fieldNames = bindingResult.getFieldErrors().stream()
147	            .map(FieldError::getField)
148	            .distinct()
149	            .toList();
150	        detail.setProperty("errors", fieldNames);
151	        if (bindingResult.hasErrors()) {
152	            errors.addAllErrors(bindingResult);
153	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
154	                .map(fieldError -> {
155	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
156	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
157	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
158	                        fieldError.getField(),
159	                        defaultMessage,
160	                        rejectedValue);
161	                    return new ValidationMessageDto(message)
162	                        .putAdditionalProperty("field", fieldError.getField())
163	                        .putAdditionalProperty("rejectedValue", rejectedValue)
164	                        .putAdditionalProperty("defaultMessage", defaultMessage);
165	                })
166	                .toList();
167	            logger.debug("Validation error at {} {}: {}",
168	                request.getMethod(),
169	                request.getRequestURI(),
170	                bindingResult.getFieldErrors());
171	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
172	            return ResponseEntity.status(status).body(detail);
173	        }
174	        return ResponseEntity.status(status).body(detail);
175	    }
