256	        HttpStatus status = HttpStatus.CONFLICT;
257	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
258	        detail.setProperty("errors", List.of("identityKey"));
259	        logger.debug("Duplicate owner identity at {} {}: {}",
260	            request.getMethod(),
261	            request.getRequestURI(),
262	            e.getMessage());
263	        return ResponseEntity.status(status).body(detail);
264	    }
265	
266	    /**
267	     * Handles {@link CityOwnerCapacityExceededException} raised when an owner is created in a city
268	     * that has already reached its maximum number of owners. Returns a 409 Conflict whose body
269	     * carries an {@code errors} array naming the offending {@code city} field.
270	     *
271	     * @param e The {@link CityOwnerCapacityExceededException} to be handled
272	     * @param request {@link HttpServletRequest} object referring to the current request.
273	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
274	     */
275	    @ExceptionHandler(CityOwnerCapacityExceededException.class)
276	    @ResponseBody
277	    public ResponseEntity<ProblemDetail> handleCityOwnerCapacityExceededException(CityOwnerCapacityExceededException e, HttpServletRequest request) {
278	        HttpStatus status = HttpStatus.CONFLICT;
279	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
