300	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
301	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
302	        logger.debug("Daily registration limit exceeded at {} {}: {}",
303	            request.getMethod(),
304	            request.getRequestURI(),
305	            e.getMessage());
306	        return ResponseEntity.status(status).body(detail);
307	    }
